import os
import signal
import spidev
import picamera2
import adafruit_mcp3008.MCP3008
import adafruit_mcp3008.util
import adafruit_circuitpython_mcp3008
import adafruit_circuitpython_mcp3008.util
import time
import json
import requests
import logging
import logging.config
import gpiozero
import math

# Set up logging
logging.config.dictConfig({
    'version': 1,
    'formatters': {
        'default': {
            'format': '[%(asctime)s] %(levelname)s in %(module)s: %(message)s',
        }
    },
    'handlers': {
        'console': {
            'class': 'logging.StreamHandler',
            'formatter': 'default',
            'level': 'DEBUG',
        },
        'file': {
            'class': 'logging.FileHandler',
            'filename': 'sound_level.log',
            'formatter': 'default',
            'level': 'DEBUG',
        }
    },
    'root': {
        'level': 'DEBUG',
        'handlers': ['console', 'file']
    }
})

# Set up signal handlers
def signal_handler(sig, frame):
    logging.info('Received signal %s, shutting down', sig)
    if 'simulated_data' in globals():
        logging.info('Falling back to simulated data')
    if 'output_pin' in globals():
        output_pin = gpiozero.Output(gpiozero.Output(0))
        output_pin.off()
    else:
        logging.info('No output pin set')
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Parse command-line arguments
import argparse
parser = argparse.ArgumentParser(description='Read sound level from KY-038 sound sensor via MCP3008 ADC')
parser.add_argument('--clk', type=int, default=17, help='SPI clock pin')
parser.add_argument('--miso', type=int, default=13, help='SPI MISO pin')
parser.add_argument('--mosi', type=int, default=19, help='SPI MOSI pin')
parser.add_argument('--cs', type=int, default=12, help='SPI CS pin')
parser.add_argument('--window', type=int, default=10, help='Moving average window size')
parser.add_argument('--rate', type=int, default=500, help='Sampling rate (Hz)')
parser.add_argument('--threshold', type=float, default=0.5, help='Threshold for output pin')
parser.add_argument('--hysteresis', type=float, default=0.05, help='Hysteresis for output pin')
parser.add_argument('--output_pin', type=int, default=0, help='Output pin for sound level')
parser.add_argument('--simulated_data', action='store_true', help='Use simulated data instead of actual sensor readings')
parser.add_argument('--duration', type=int, default=None, help='Run for a specified duration (seconds)')
args = parser.parse_args()

# Set up SPI
try:
    spi = spidev.SpiDev()
    spi.open(args.clk, args.miso, args.mosi, args.cs)
except spidev.CircuitPythonError as e:
    logging.error('Failed to initialize SPI: %s', e)
    spi = None

# Set up ADC
if spi is not None:
    adc = adafruit_mcp3008.MCP3008.MCP3008(spi, clock=spi.xfer2)
else:
    logging.info('Falling back to simulated data')
    adc = None

# Set up output pin
try:
    output_pin = gpiozero.Output(args.output_pin)
except gpiozero.GpioError as e:
    logging.error('Failed to set up output pin: %s', e)
    output_pin = None

# Set up camera (for logging)
try:
    camera = picamera2.PiCamera()
    camera.resolution = (640, 480)
    camera.framerate = 30
except picamera2.CaptureError as e:
    logging.error('Failed to initialize camera: %s', e)
    camera = None

# Set up moving average filter
def moving_average(data, window):
    return sum(data[-window:]) / window

# Set up logging and HTTP client
def log_data(data):
    logging.info('Sound level: %f', data)
    if camera is not None:
        camera.capture('sound_level.png')
    data = {'sound_level': data}
    try:
        response = requests.post('https://your-cloud-service.com/api/sound-level', json=data)
        response.raise_for_status()
    except requests.RequestException as e:
        logging.error('Failed to upload data: %s', e)

# Main loop
if 'simulated_data' in globals():
    data = [0.5] * 100
    while True:
        if 'output_pin' in globals():
            if data[-1] > args.threshold + args.hysteresis:
                output_pin.on()
            elif data[-1] < args.threshold - args.hysteresis:
                output_pin.off()
        log_data(moving_average(data, args.window))
        time.sleep(1 / args.rate)
        data.append(data[-1])
        data.pop(0)
else:
    try:
        while True:
            if 'output_pin' in globals():
                if adc is not None:
                    try:
                        reading = adc.read(0)
                        reading = reading[0] / 1023.0
                        reading = moving_average([reading] + data[-args.window:], args.window)
                        if reading > args.threshold + args.hysteresis:
                            output_pin.on()
                        elif reading < args.threshold - args.hysteresis:
                            output_pin.off()
                        log_data(reading)
                    except adafruit_mcp3008.MCP3008.Error as e:
                        logging.error('Failed to read ADC: %s', e)
                else:
                    logging.info('No ADC available')
            else:
                logging.info('No output pin set')
            time.sleep(1 / args.rate)
            data.append(reading)
            data.pop(0)
    except KeyboardInterrupt:
        logging.info('Received interrupt, shutting down')
    except Exception as e:
        logging.error('Unexpected error: %s', e)
    finally:
        if 'output_pin' in globals():
            output_pin.off()
        if 'simulated_data' in globals():
            logging.info('Falling back to simulated data')
        if adc is not None:
            adc.close()
        if camera is not None:
            camera.close()
        if spi is not None:
            spi.close()

