import spidev
import picamera2
import adafruit_mcp3008.MCP3008
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.mcp3008 = adafruit_mcp3008.MCP3008.MCP3008()
        self.spi.open(0, 0, max_speed_hz=50000, mode=0b00, bits_per_word=8)
        self.spi.xfer2([0x01, 0x80, 0x00])
        self.spi.close()

    def read_raw_data(self):
        try:
            self.spi.open(0, 0, max_speed_hz=50000, mode=0b00, bits_per_word=8)
            response = self.spi.xfer2([0x01, 0x80, 0x00])
            self.spi.close()
            return response
        except (OSError, IOError) as e:
            print(f"Error reading from SPI device: {e}")
            return None

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        self.spi.close()

def signal_handler(sig, frame):
    print("\nShutting down...")
    sys.exit(0)

def main():
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            if raw_data is not None:
                weight = reader.convert_to_weight(raw_data)
                if weight is not None:
                    print(f"Weight: {weight:.2f} kg", end='\r')
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nShutting down...")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        reader.close()

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)
    main()

