import logging
import smbus2
import picamera2
import adafruit_ads1x15.ads1015 as ads
import adafruit_ads1x15.analog_in as analog_in
import time
import threading
import atexit
import signal

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.i2c_bus = None
        self.ads = None
        self.channel = None
        self.pga = 6144
        self.sps = 250
        self.last_conversion_result = None

        self.i2c_bus = smbus2.SMBus(self.busnum)
        try:
            self.i2c_bus = smbus2.SMBus(self.busnum)
            self.ads = ads.ADS1015(self.address, self.i2c_bus)
            self.channel = analog_in.AnalogIn(self.ads, 0)
        except smbus2.SMBusError as e:
            logger.error(f"Failed to initialize I2C bus: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            result = self.channel.read_vref(self.pga, self.sps)
            if self.debug:
                logger.info(f"ADC single-ended reading: {result}")
            return int(result)
        except Exception as e:
            logger.error(f"Failed to read ADC single-ended: {e}")
            raise

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.config_channel(channel, self.pga, self.sps)
            self.ads.start_continuous_conversion()
            if self.debug:
                logger.info(f"Started continuous conversion on channel {channel}")
        except Exception as e:
            logger.error(f"Failed to start continuous conversion: {e}")
            raise

    def get_last_conversion_results(self):
        try:
            result = self.ads.read_results()
            if self.debug:
                logger.info(f"Last conversion results: {result}")
            return result
        except Exception as e:
            logger.error(f"Failed to get last conversion results: {e}")
            raise

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self.ads.config_channel(channel, self.pga, self.sps)
            self.ads.config_comparator(threshold_high, threshold_low, active_low, traditional_mode, latching)
            self.ads.start_comparator()
            if self.debug:
                logger.info(f"Started single-ended comparator on channel {channel}")
            return self.ads.read_comparator(num_readings)
        except Exception as e:
            logger.error(f"Failed to start single-ended comparator: {e}")
            raise

    def __del__(self):
        if self.ads:
            self.ads.stop()
            self.ads = None
        if self.i2c_bus:
            self.i2c_bus.close()
            self.i2c_bus = None

def signal_handler(sig, frame):
    if hasattr(ADS1015, 'i2c_bus'):
        ADS1015.i2c_bus.close()
    exit()

if __name__ == "__main__":
    ads = ADS1015(debug=True)
    ads.start_continuous_conversion(channel=0)
    time.sleep(1)
    print(ads.get_last_conversion_results())
    ads.start_single_ended_comparator(channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1)
    time.sleep(1)
    ads.stop_continuous_conversion()
    ads.stop_comparator()
    ads = None
    atexit.register(signal_handler)

import logging
import os
import signal
import spidev
import time
import adafruit_dht
import adafruit_circuitpython_mcp3008
import gpiozero
import picamera2
import paho.mqtt.client as mqtt

# Set up logging
logging.basicConfig(filename='greenhouse.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Set up GPIO pins
try:
    import RPi.GPIO as GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(4, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(17, GPIO.OUT)
    GPIO.setup(22, GPIO.OUT)
    GPIO.setup(25, GPIO.OUT)
    GPIO.setup(27, GPIO.OUT)
    GPIO.setup(8, GPIO.OUT)
    GPIO.setup(10, GPIO.OUT)
    GPIO.setup(9, GPIO.IN)
    GPIO.setup(11, GPIO.OUT)
except Exception as e:
    logging.error('Failed to set up GPIO pins: %s', e)
    exit(1)

# Set up SPI device
try:
    spidev = spidev.SpiDev()
    spidev.open(0, 0)
except Exception as e:
    logging.error('Failed to open SPI device: %s', e)
    exit(1)

# Set up DHT22 sensor
try:
    dht = adafruit_dht.DHT22()
    dht.data_pin = 4
except Exception as e:
    logging.error('Failed to initialize DHT22 sensor: %s', e)
    exit(1)

# Set up relays
try:
    pump = gpiozero.CircuitPythonRelay(17)
    fan = gpiozero.CircuitPythonRelay(27)
    light = gpiozero.CircuitPythonRelay(22)
except Exception as e:
    logging.error('Failed to initialize relays: %s', e)
    exit(1)

# Set up LED
try:
    led = gpiozero.CircuitPythonLED(25)
except Exception as e:
    logging.error('Failed to initialize LED: %s', e)
    exit(1)

# Set up camera
try:
    camera = picamera2.PiCamera()
except Exception as e:
    logging.error('Failed to initialize camera: %s', e)
    exit(1)

# Set up MQTT client
try:
    client = mqtt.Client()
    client.connect('localhost', 1883)
except Exception as e:
    logging.error('Failed to connect to MQTT broker: %s', e)
    exit(1)

# Set up watchdog
import time
import threading
import os
watchdog = threading.Event()
watchdog.clear()

def watchdog_timeout():
    logging.error('Watchdog timed out')
    os.execv('/bin/sh', ['sh', '-c', 'sudo reboot'])

def signal_handler(sig, frame):
    logging.info('Received signal %s', sig)
    watchdog.set()
    os._exit(0)

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

def read_dht():
    try:
        temperature, humidity = dht.read()
        logging.info('Temperature: %f°C, Humidity: %f%%', temperature, humidity)
        return temperature, humidity
    except Exception as e:
        logging.error('Failed to read DHT22 sensor: %s', e)
        return None, None

def control_pump(command):
    if command == 'on':
        pump.on()
    elif command == 'off':
        pump.off()
    else:
        logging.error('Invalid pump command: %s', command)

def control_fan(command):
    if command == 'on':
        fan.on()
    elif command == 'off':
        fan.off()
    else:
        logging.error('Invalid fan command: %s', command)

def control_light(command):
    if command == 'on':
        light.on()
    elif command == 'off':
        light.off()
    else:
        logging.error('Invalid light command: %s', command)

def set_led_status(status):
    if status == 'online':
        led.on()
    elif status == 'offline':
        led.off()
    elif status == 'error':
        led.blink(5, 0.2)
    elif status == 'synchronizing':
        led.blink(5, 0.2)
    else:
        logging.error('Invalid LED status: %s', status)

def read_mcp3008():
    try:
        data = spidev.xfer([0x00, 0x00, 0x00, 0x00], 0, 0, 1000)
        return data
    except Exception as e:
        logging.error('Failed to read MCP3008: %s', e)
        return None

def main():
    while True:
        try:
            temperature, humidity = read_dht()
            if temperature is None:
                logging.warning('DHT22 sensor not found')
                continue
            logging.info('Temperature: %f°C, Humidity: %f%%', temperature, humidity)
            if temperature > 30:
                control_pump('on')
                control_fan('on')
                set_led_status('synchronizing')
            else:
                control_pump('off')
                control_fan('off')
                set_led_status('online')
            data = read_mcp3008()
            if data is not None:
                logging.info('MCP3008 reading: %s', data)
            time.sleep(300)
        except Exception as e:
            logging.error('Error: %s', e)
            watchdog.set()
            time.sleep(1)
        if watchdog.wait(600):
            watchdog_timeout()

if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        logging.error('Error: %s', e)
    finally:
        GPIO.cleanup()
        spidev.close()
        client.disconnect()
        os._exit(0)

