    GPIO.setup(25, GPIO.OUT)
    GPIO.setup(27, GPIO.OUT)
    GPIO.setup(8, GPIO.OUT)
    GPIO.setup(10, GPIO.OUT)
    GPIO.setup(9, GPIO.IN)
    GPIO.setup(11, GPIO.OUT)
except Exception as e:
    logging.error('Failed to set up GPIO pins: %s', e)
    exit(1)

# Set up SPI device
try:
    spidev = spidev.SpiDev()
    spidev.open(0, 0)
except Exception as e:
    logging.error('Failed to open SPI device: %s', e)
    exit(1)

# Set up DHT22 sensor
try:
    dht = adafruit_dht.DHT22()
    dht.data_pin = 4
except Exception as e:
    logging.error('Failed to initialize DHT22 sensor: %s', e)
    exit(1)

# Set up relays
try:
    pump = gpiozero.CircuitPythonRelay(17)
    fan = gpiozero.CircuitPythonRelay(27)
    light = gpiozero.CircuitPythonRelay(22)
except Exception as e:
    logging.error('Failed to initialize relays: %s', e)
    exit(1)

# Set up LED
try:
    led = gpiozero.CircuitPythonLED(25)
except Exception as e:
    logging.error('Failed to initialize LED: %s', e)
    exit(1)

# Set up camera
try:
    camera = picamera2.PiCamera()
except Exception as e:
    logging.error('Failed to initialize camera: %s', e)
    exit(1)

# Set up MQTT client
try:
    client = mqtt.Client()
    client.connect('localhost', 1883)
except Exception as e:
    logging.error('Failed to connect to MQTT broker: %s', e)
    exit(1)

# Set up watchdog
import time
import threading
import os
watchdog = threading.Event()
watchdog.clear()

def watchdog_timeout():
    logging.error('Watchdog timed out')
    os.execv('/bin/sh', ['sh', '-c', 'sudo reboot'])

def signal_handler(sig, frame):
    logging.info('Received signal %s', sig)
    watchdog.set()
    os._exit(0)

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

def read_dht():
    try:
        temperature, humidity = dht.read()
        logging.info('Temperature: %f°C, Humidity: %f%%', temperature, humidity)
        return temperature, humidity
    except Exception as e:
        logging.error('Failed to read DHT22 sensor: %s', e)
        return None, None

def control_pump(command):
    if command == 'on':
        pump.on()
    elif command == 'off':
        pump.off()
    else:
        logging.error('Invalid pump command: %s', command)

def control_fan(command):
    if command == 'on':
        fan.on()
    elif command == 'off':
        fan.off()
    else:
        logging.error('Invalid fan command: %s', command)

def control_light(command):
    if command == 'on':
        light.on()
    elif command == 'off':
        light.off()
    else:
        logging.error('Invalid light command: %s', command)

def set_led_status(status):
    if status == 'online':
        led.on()
    elif status == 'offline':
        led.off()
    elif status == 'error':
        led.blink(5, 0.2)
    elif status == 'synchronizing':
        led.blink(5, 0.2)
    else:
        logging.error('Invalid LED status: %s', status)

def read_mcp3008():
    try:
        data = spidev.xfer([0x00, 0x00, 0x00, 0x00], 0, 0, 1000)
        return data
    except Exception as e:
        logging.error('Failed to read MCP3008: %s', e)
        return None

def main():
    while True:
        try:
            temperature, humidity = read_dht()
            if temperature is None:
                logging.warning('DHT22 sensor not found')
                continue
            logging.info('Temperature: %f°C, Humidity: %f%%', temperature, humidity)
            if temperature > 30:
                control_pump('on')
                control_fan('on')
                set_led_status('synchronizing')
            else:
                control_pump('off')
                control_fan('off')
                set_led_status('online')
            data = read_mcp3008()
            if data is not None:
                logging.info('MCP3008 reading: %s', data)
            time.sleep(300)
        except Exception as e:
            logging.error('Error: %s', e)
            watchdog.set()
            time.sleep(1)
        if watchdog.wait(600):
            watchdog_timeout()

if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        logging.error('Error: %s', e)
    finally:
        GPIO.cleanup()
        spidev.close()
        client.disconnect()
        os._exit(0)
