import sys
import threading
from gpiozero import PWM
from picamera2 import PiCamera
from adafruit_mcp3008 import MCP3008
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(filename='quality_control.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def read_mcp3008(channel):
    """Read a single-ended channel from the MCP3008 ADC."""
    try:
        with MCP3008(0, spi_bus, spi_device) as adc:
            result = adc.read_mcp3008(channel)
            return (result >> 3) & 0x3F
    except Exception as e:
        logging.error(f"Error reading MCP3008 channel {channel}: {e}")
        return None

def read_flow_rate(channel):
    """Map an ADC value to a flow rate of 0-102.3 mL/min."""
    return int((read_mcp3008(channel) / 4096) * 102.3)

def set_actuator_position(pin, angle):
    """Map an angle of 0-180 degrees to a PWM duty cycle of 5-10%."""
    if not 0 <= angle <= 180:
        logging.error(f"Invalid angle {angle} for pin {pin}. Skipping.")
        return
    try:
        pwm = PWM(pin, frequency=100)
        pwm.duty = int((angle / 180) * 10)
    except Exception as e:
        logging.error(f"Error setting PWM on pin {pin}: {e}")

def control_flow(pin, target_flow_rate):
    """Apply proportional control to adjust the actuator angle."""
    try:
        current_flow_rate = read_flow_rate(pin)
        error = target_flow_rate - current_flow_rate
        new_angle = int((error / 2) * 180)
        set_actuator_position(pin, new_angle)
    except Exception as e:
        logging.error(f"Error controlling flow on pin {pin}: {e}")

def main():
    # Parse command-line arguments
    parser = argparse.ArgumentParser(description='Control flow using proportional control.')
    parser.add_argument('--pins', required=True, help='Comma-separated BCM GPIO numbers for actuator PWM outputs.')
    parser.add_argument('--spi_bus', type=int, default=0, help='SPI bus number.')
    parser.add_argument('--spi_device', type=int, default=0, help='SPI device number.')
    parser.add_argument('--interval', type=float, default=1.0, help='Interval between control loop iterations in seconds.')
    parser.add_argument('--tolerance', type=float, default=5.0, help='Tolerance in percent.')
    parser.add_argument('--target_flows', required=True, help='Comma-separated target flow rates in mL/min, one per actuator.')
    args = parser.parse_args()

    # Initialize GPIO
    try:
        pins = [int(pin) for pin in args.pins.split(',')]
        for pin in pins:
            try:
                pwm = PWM(pin, frequency=100)
            except Exception as e:
                logging.error(f"Error initializing PWM on pin {pin}: {e}")
                return
    except ValueError:
        logging.error("Invalid pin values. Exiting.")
        return

    # Initialize SPI
    try:
        spi = spidev(spi_bus, spi_device, max_speed=1000000)
    except Exception as e:
        logging.error(f"Error initializing SPI: {e}")
        return

    # Initialize MCP3008
    try:
        mcp3008 = MCP3008(spi_bus, spi_device)
    except Exception as e:
        logging.error(f"Error initializing MCP3008: {e}")
        return

    # Initialize MQTT client
    try:
        client = MQTTClient('quality_control', 'localhost')
        client.connect()
    except Exception as e:
        logging.error(f"Error initializing MQTT client: {e}")
        return

    # Main loop
    try:
        while True:
            for pin in pins:
                control_flow(pin, read_flow_rate(pin))
            time.sleep(args.interval)
    except KeyboardInterrupt:
        logging.info('Stopping control loop.')
    except Exception as e:
        logging.error(f"Error in main loop: {e}")
    finally:
        # Clean up
        for pin in pins:
            try:
                pwm.stop()
            except Exception as e:
                logging.error(f"Error stopping PWM on pin {pin}: {e}")
        try:
            spi.close()
        except Exception as e:
            logging.error(f"Error closing SPI: {e}")
        try:
            client.disconnect()
        except Exception as e:
            logging.error(f"Error disconnecting MQTT client: {e}")
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")

if __name__ == '__main__':
    main()

