import logging
import json
import time
import random
import signal
import sys
from gpiozero import CPUTimeoutError, MCP3008
from picamera2 import PiCamera
from paho.mqtt.client import MQTTClient, MQTTConnectError
from RPi.GPIO import GPIO

# Set up logging
logging.basicConfig(filename='greenhouse_monitor.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)

def get_soil_moisture():
    try:
        sensor = MCP3008(channel=0)
        reading = sensor.value
        if reading == 0 or reading == 1023:
            return random.randint(0, 100)
        return reading
    except CPUTimeoutError:
        logger.warning('Timeout reading soil moisture sensor')
        return None

def get_weather_forecast():
    try:
        with open('weather_forecast.json') as f:
            data = json.load(f)
            return data['rain_probability']
    except FileNotFoundError:
        logger.error('Missing weather forecast file')
        return None
    except json.JSONDecodeError:
        logger.error('Invalid JSON in weather forecast file')
        return None

def control_watering(soil_moisture, rain_probability):
    if soil_moisture is None or rain_probability is None:
        logger.warning('Missing data')
        return
    if soil_moisture < 30 and rain_probability < 0.2:
        GPIO.output(17, GPIO.HIGH)
    elif soil_moisture > 70:
        GPIO.output(17, GPIO.LOW)
    else:
        pass

def main():
    try:
        while True:
            soil_moisture = get_soil_moisture()
            rain_probability = get_weather_forecast()
            control_watering(soil_moisture, rain_probability)
            logger.info(f'Soil moisture: {soil_moisture}%')
            logger.info(f'Rain probability: {rain_probability}')
            time.sleep(60)
    except KeyboardInterrupt:
        logger.info('Stopping program')
    except SystemExit:
        logger.info('Stopping program')
    except Exception as e:
        logger.error(f'Error: {e}')
    finally:
        GPIO.cleanup()
        logger.info('GPIO cleanup complete')

def signal_handler(sig, frame):
    logger.info('Stopping program')
    GPIO.cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    main()

import cv2
import signal
import sys
import time
from gpiozero import LED, Button, AngularServo
import picamera2
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
import paho.mqtt.client as mqtt

# Set up signal handlers
def signal_handler(sig, frame):
    print('Caught signal, exiting cleanly')
    cleanup()

def cleanup():
    try:
        if camera:
            camera.close()
    except AttributeError:
        pass
    if window:
        window.destroy()
    if servo:
        servo.stop()
    if led:
        led.off()
    if button:
        button.deactivate()
    if mqtt_client:
        mqtt_client.disconnect()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Set up GPIO
try:
    led = LED(14)
    button = Button(15, pull_up=True)
    servo = AngularServo(18)
except Exception as e:
    print(f"Failed to initialize GPIO: {e}")
    sys.exit(1)

# Set up MQTT client
try:
    mqtt_client = mqtt.Client()
    mqtt_client.connect("localhost", 1883)
except Exception as e:
    print(f"Failed to connect to MQTT: {e}")
    sys.exit(1)

# Load cascade classifier
try:
    face_cascade = cv2.CascadeClassifier("/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml")
except FileNotFoundError:
    print("Face cascade file not found")
    sys.exit(1)
except Exception as e:
    print(f"Failed to load face cascade: {e}")
    sys.exit(1)

# Set up camera
try:
    camera = PiCamera()
    camera.resolution = (320, 240)
    camera.framerate = 50
except Exception as e:
    print(f"Failed to initialize camera: {e}")
    sys.exit(1)

# Set up window
try:
    window = cv2.namedWindow("Human Detection")
    cv2.namedWindow("Camera Feed")
except Exception as e:
    print(f"Failed to create window: {e}")
    sys.exit(1)

# Main loop
while True:
    try:
        # Read frame from camera
        frame = camera.capture_continuous(format="bgr", use_video_port=True)

        # Convert frame to OpenCV image
        image = np.frombuffer(frame, dtype=np.uint8)

        # Convert image to grayscale
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)

        # Detect faces
        faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5)

        # Draw rectangles around detected faces
        for (x, y, w, h) in faces:
            cv2.rectangle(image, (x, y), (x+w, y+h), (0, 255, 0), 2)

        # Map servo angle to face center
        if faces:
            center_x = int(image.shape[1] / 2)
            center_y = int(image.shape[0] / 2)
            if center_x < faces[0][0] + faces[0][2] / 2:
                servo.angle = 20
            else:
                servo.angle = 160
            if center_y < faces[0][1] + faces[0][3] / 2:
                servo.angle = 20
            else:
                servo.angle = 160
            if servo.angle < 0:
                servo.angle = 0
            elif servo.angle > 180:
                servo.angle = 180

        # Turn LED on if at least one face is detected
        if faces:
            led.on()
        else:
            led.off()

        # Display frame
        cv2.imshow("Human Detection", image)
        cv2.imshow("Camera Feed", image)

        # Check for 'q' key press
        if cv2.waitKey(1) & 0xFF == ord('q'):
            break

    except Exception as e:
        print(f"Error in main loop: {e}")

    finally:
        cleanup()

import board
import busio
import adafruit_bmp280
import adafruit_bme280
import adafruit_ms8607
import sqlite3
import logging
import time
import datetime
import signal
import sys

# Set up logging
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

# Load configuration from config.txt
try:
    with open('config.txt', 'r') as f:
        config = {}
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=')
                config[key] = value
except FileNotFoundError:
    logging.error('Missing config.txt file')
    sys.exit(1)

# Set up I2C bus
i2c = busio.I2C(board.SCL, board.SDA)

# Set up sensors
sensors = {}
for sensor_type, address in [('BMP280', 0x76), ('BME280', 0x77), ('MS8607', 0x78)]:
    if sensor_type not in config:
        logging.warning(f'Missing configuration for {sensor_type}')
        continue
    if address not in [0x76, 0x77, 0x78]:
        logging.warning(f'Invalid address for {sensor_type}')
        continue
    try:
        if sensor_type == 'BMP280':
            sensor = adafruit_bmp280.BMP280(i2c, address=address)
        elif sensor_type == 'BME280':
            sensor = adafruit_bme280.BME280(i2c, address=address)
        elif sensor_type == 'MS8607':
            sensor = adafruit_ms8607.MS8607(i2c, address=address)
        sensors[sensor_type] = sensor
    except Exception as e:
        logging.error(f'Failed to initialize {sensor_type}: {e}')
        continue

# Set up database
try:
    conn = sqlite3.connect('wildlife_data.db')
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS sensor_data
        (timestamp TEXT, sensor_type TEXT, sensor_id INTEGER, pressure_pa REAL, temperature_c REAL, humidity_percent REAL)
    ''')
except sqlite3.Error as e:
    logging.error(f'Failed to create database table: {e}')
    conn = None

def read_sensors():
    try:
        for sensor_type, sensor in sensors.items():
            if sensor_type not in config:
                continue
            if sensor_type == 'BMP280':
                pressure = sensor.pressure / 100
                temperature = sensor.temperature
                humidity = None
            elif sensor_type == 'BME280':
                pressure = sensor.pressure / 100
                temperature = sensor.temperature
                humidity = sensor.humidity
            elif sensor_type == 'MS8607':
                pressure = sensor.pressure
                temperature = sensor.temperature
                humidity = sensor.humidity
            if pressure < 70000 or pressure > 110000:
                logging.warning(f'Invalid pressure reading for {sensor_type}: {pressure}')
                continue
            if temperature < -20 or temperature > 50:
                logging.warning(f'Invalid temperature reading for {sensor_type}: {temperature}')
                continue
            if humidity is not None and humidity < 0 or humidity > 100:
                logging.warning(f'Invalid humidity reading for {sensor_type}: {humidity}')
                continue
            timestamp = datetime.datetime.now().isoformat()
            c.execute('INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?, ?)', (timestamp, sensor_type, sensor.id, pressure, temperature, humidity))
            conn.commit()
    except Exception as e:
        logging.error(f'Failed to read sensors: {e}')

def main():
    try:
        while True:
            read_sensors()
            time.sleep(int(config.get('Sampling_Interval_Seconds', 60))
    except KeyboardInterrupt:
        if conn:
            conn.close()
        sys.exit(0)

def signal_handler(sig, frame):
    if conn:
        conn.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

if __name__ == '__main__':
    main()

