logger = logging.getLogger(__name__)

# Set up I2C bus
try:
    bus = SMBus(1)  # Use I2C bus 1
except OSError as e:
    logger.error(f"I2C bus not available: {e}")
    sys.exit(1)

# Set up sensor
try:
    sensor = bus.open(0x69)  # Open AMG8833 sensor at address 0x69
except (IOError, OSError) as e:
    logger.error(f"Failed to open sensor: {e}")
    sys.exit(1)

# Set up camera
try:
    camera = PiCamera()
except Exception as e:
    logger.error(f"Failed to initialize camera: {e}")
    sys.exit(1)

# Set up MQTT client
try:
    client = MQTTClient('thermal_monitor', 'your_broker_url', 1883)
except Exception as e:
    logger.error(f"Failed to initialize MQTT client: {e}")
    sys.exit(1)

# Set up signal handler for KeyboardInterrupt
def signal_handler(sig, frame):
    logger.info("Received KeyboardInterrupt, shutting down...")
    release_resources()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

# Set up heatmap directory
try:
    os.makedirs('/home/pi/thermal_logs', exist_ok=True)
except OSError as e:
    logger.error(f"Failed to create thermal logs directory: {e}")
    sys.exit(1)

# Main loop
try:
    while True:
        try:
            # Read temperature pixel array
            try:
                temperatures = np.array([sensor.read_byte(0x00) for _ in range(64)])
            except (IOError, OSError) as e:
                logger.error(f"Failed to read temperature pixel array: {e}")
                continue

            # Calculate average temperature
            average_temperature = np.mean(temperatures)

            # Check for alert
            if average_temperature > 70.0:
                logger.warning(f"Average temperature exceeded 70.0°C: {average_temperature:.2f}°C")
                print(f"Average temperature exceeded 70.0°C: {average_temperature:.2f}°C")

            # Save heatmap
            try:
                plt.imshow(temperatures, cmap='jet', interpolation='none')
                plt.savefig('/home/pi/thermal_logs/thermal_image_YYYYMMDD_HHMMSS.png')
            except Exception as e:
                logger.error(f"Failed to save heatmap: {e}")

            # Log data
            try:
                with open('/home/pi/thermal_logs/thermal_data.csv', 'a', newline='') as csvfile:
                    writer = csv.writer(csvfile)
                    writer.writerow([time.time(), average_temperature, temperatures.flatten()])
            except IOError as e:
                logger.error(f"Failed to log data: {e}")

            # Sleep for 1 second to maintain 1 Hz
            time.sleep(1)

except KeyboardInterrupt:
    logger.info("Received KeyboardInterrupt, shutting down...")
    release_resources()
    sys.exit(0)

except Exception as e:
    logger.error(f"Unexpected error: {e}")
    release_resources()
    sys.exit(1)

def release_resources():
    try:
        sensor.close()
    except (IOError, OSError) as e:
        logger.error(f"Failed to close sensor: {e}")
    try:
        camera.close()
    except Exception as e:
        logger.error(f"Failed to close camera: {e}")
    try:
        client.disconnect()
    except Exception as e:
        logger.error(f"Failed to disconnect MQTT client: {e}")
    try:
        os.remove('/home/pi/thermal_logs/thermal_image_YYYYMMDD_HHMMSS.png')
    except IOError as e:
        logger.error(f"Failed to remove heatmap image: {e}")
    try:
        os.remove('/home/pi/thermal_logs/thermal_data.csv')
    except IOError as e:
        logger.error(f"Failed to remove log file: {e}")

