# Set up GPIO pins
try:
    GPIO.setup(17, GPIO.OUT)
except Exception as e:
    logger.error(f"Failed to set up GPIO pin 17: {e}")

# Set up DHT11 sensor
try:
    dht_device = adafruit_dht.DHT11()
except Exception as e:
    logger.error(f"Failed to initialize DHT11 sensor: {e}")
    dht_device = None

# Set up camera
try:
    camera = picamera2.PiCamera()
except Exception as e:
    logger.error(f"Failed to initialize camera: {e}")
    camera = None

# Set up microphone
mic = sr.Microphone()

# Set up speech recognition
recognizer = sr.Recognizer()

# Set up signal handlers
def signal_handler(sig, frame):
    GPIO.cleanup()
    if camera:
        camera.close()
    if dht_device:
        dht_device.close()
    logger.info("Exiting")
    os._exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def turn_lights_on():
    try:
        GPIO.output(17, GPIO.HIGH)
    except Exception as e:
        logger.error(f"Failed to turn on lights: {e}")

def turn_lights_off():
    try:
        GPIO.output(17, GPIO.LOW)
    except Exception as e:
        logger.error(f"Failed to turn off lights: {e}")

def read_temperature():
    if dht_device:
        try:
            temperature = dht_device.temperature
            return temperature
        except Exception as e:
            logger.error(f"Failed to read temperature: {e}")
            return None
    else:
        return round((15 + 20 * (35 - 15) / 70), 2)

def take_picture():
    if camera:
        try:
            timestamp = datetime.now().strftime("%Y-%m-%d-%H-%M-%S")
            camera.capture(f"greenhouse_{timestamp}.jpg")
            logger.info(f"Picture taken and saved as greenhouse_{timestamp}.jpg")
        except Exception as e:
            logger.error(f"Failed to take picture: {e}")

def listen_for_commands():
    while True:
        with mic as source:
            try:
                audio = recognizer.listen(source, timeout=5)
                try:
                    audio = audio.get_data()
                    logger.info(f"Received audio: {audio}")
                    speech = recognizer.recognize_google(audio, language="en-US")
                    logger.info(f"Recognized speech: {speech}")
                    if speech.startswith("Greenhouse"):
                        if speech == "turn on the lights":
                            turn_lights_on()
                        elif speech == "turn off the lights":
                            turn_lights_off()
                        elif speech == "what is the temperature":
                            temperature = read_temperature()
                            if temperature:
                                logger.info(f"Temperature: {temperature}°C")
                            else:
                                logger.info("Failed to read temperature")
                        elif speech == "take a picture":
                            take_picture()
                except sr.UnknownValueError:
                    logger.info("Speech recognition failed")
            except Exception as e:
                logger.error(f"Failed to listen for commands: {e}")

def main():
    try:
        threading.Thread(target=listen_for_commands).start()
        while True:
            time.sleep(1)
    except Exception as e:
        logger.error(f"Failed to start listening for commands: {e}")

if __name__ == "__main__":
    main()

