from gpiozero import CPUTimer
from gpiozero import LED

# Load configuration
config = configparser.ConfigParser()
config.read('config.ini')

# Set up logging
logging.basicConfig(filename='inventory.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logging.getLogger('picamera2').setLevel(logging.ERROR)
logging.getLogger('picamera2.video').setLevel(logging.ERROR)

# Set up camera parameters
camera0 = None
camera1 = None
camera0_buffer = None
camera1_buffer = None
redundancy_time_window = float(config['DEFAULT']['redundancy_time_window'])
cloud_upload_interval = int(config['DEFAULT']['cloud_upload_interval'])
frame_buffer_size = int(config['DEFAULT']['frame_buffer_size'])
reinit_delay = float(config['DEFAULT']['reinit_delay'])
watchdog_timeout = 30

# Set up MQTT client
mqtt_client = mqtt.Client()
mqtt_client.connect(config['MQTT']['broker'], config['MQTT']['port'])

# Set up watchdog
watchdog = CPUTimer(watchdog_timeout)

# Set up camera threads
camera0_thread = None
camera1_thread = None

# Set up frame buffers
camera0_buffer = queue.Queue(frame_buffer_size)
camera1_buffer = queue.Queue(frame_buffer_size)

# Set up LED
led = LED(config['DEFAULT']['led_pin'])

def init_camera(camera):
    try:
        camera = picamera2.PiCamera()
        camera.resolution = (config['DEFAULT']['resolution_width'], config['DEFAULT']['resolution_height'])
        camera.framerate = config['DEFAULT']['framerate']
        camera0_buffer.put(camera)
        camera1_buffer.put(camera)
        return camera
    except Exception as e:
        logging.error(f'Failed to initialize camera {camera}')
        return None

def read_camera(camera):
    try:
        camera = camera or init_camera(camera)
        if camera is None:
            return None
        while True:
            try:
                frame = camera.capture_continuous(format='bgr', use_video_port=True)
                frame = np.frombuffer(frame.array, dtype=np.uint8)
                if camera == camera0:
                    camera0_buffer.put(frame)
                else:
                    camera1_buffer.put(frame)
            except Exception as e:
                logging.error(f'Error reading camera {camera}')
                camera.release()
                return None
    except KeyboardInterrupt:
        camera.release()
        return None

def detect_motion(camera):
    try:
        while True:
            frame = camera0_buffer.get()
            if frame is None:
                continue
            frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            frame_diff = cv2.absdiff(frame, frame0)
            _, thresh = cv2.threshold(frame_diff, int(config['DEFAULT']['motion_threshold']), 255, cv2.THRESH_BINARY)
            contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            for contour in contours:
                area = cv2.contourArea(contour)
                if area > config['DEFAULT']['min_area']:
                    x, y, w, h = cv2.boundingRect(contour)
                    if config['DEFAULT']['min_ratio'] < w / h:
                        # Decode QR code
                        decoded_objects = pyzbar.decode(frame[y:y+h, x:x+w])
                        for obj in decoded_objects:
                            qr_code_data = obj.data.decode('utf-8')
                            if camera == camera0:
                                with open('inventory.log', 'a') as f:
                                    f.write(f'{time.time()} - Camera 0 - {qr_code_data}\n')
                            else:
                                try:
                                    with open('inventory.log', 'a') as f:
                                        f.write(f'{time.time()} - Camera 1 - {qr_code_data}\n')
                                except Exception as e:
                                    with open('backup_inventory.log', 'a') as f:
                                        f.write(f'{time.time()} - Camera 1 - {qr_code_data}\n')
                                if qr_code_data in camera1_buffer.queue:
                                    time.sleep(config['DEFAULT']['redundancy_time_window'])
                                    continue
                                with open('inventory.log', 'a') as f:
                                    f.write(f'{time.time()} - Camera 1 - {qr_code_data}\n')
                                camera1_buffer.put(qr_code_data)
                        # Simulate cloud upload
                        if time.time() % cloud_upload_interval == 0:
                            with open('inventory.log', 'r') as f:
                                print(f.read())
                            os.remove('inventory.log')
                            os.rename('backup_inventory.log', 'inventory.log')
            time.sleep(config['DEFAULT']['scan_interval'])
    except KeyboardInterrupt:
        camera.release()
        return None

