            logger.error(f"Error decoding JPEG frame: {e}")
            return None

    def write(self, data):
        with self.lock:
            if data.startswith(b'\xff\xd8'):
                if self.current_frame is not None:
                    self.broadcast(self.current_frame)
                self.current_frame = self._convert_to_opencv_frame(data)
                if self.current_frame is not None:
                    self.previous_frame = self.current_frame
            else:
                if self.current_frame is not None:
                    self.broadcast(self.current_frame)
                self.current_frame = None
            self.previous_frame = self.current_frame

    def flush(self):
        with self.lock:
            if self.flushing:
                return
            self.flushing = True
            if self.current_frame is not None:
