import RPi.GPIO as GPIO
import time
import signal
import threading
import numpy as np

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup([17, 18, 22, 23, 27, 4, 24, 25], GPIO.OUT)
GPIO.output([17, 18, 27, 4, 24, 25], GPIO.LOW)

# Define constants
Kp = 0.1
max_steps = 3000
max_steps_y = 2000
steps_per_second = 50

# Define functions
def move_stepper(dir_pin, step_pin, steps, direction):
    try:
        GPIO.output(dir_pin, direction)
        time.sleep(0.001)
        for _ in range(steps):
            GPIO.output(step_pin, GPIO.HIGH)
            time.sleep(0.0005)
            GPIO.output(step_pin, GPIO.LOW)
            time.sleep(0.0005)
    except Exception as e:
        print(f"Error moving stepper: {e}")

def quadrature_encoder_decode(A, B):
    if A == GPIO.HIGH and B == GPIO.LOW:
        return -1
    elif A == GPIO.LOW and B == GPIO.HIGH:
        return 1
    else:
        return 0

def get_encoder_position(A, B):
    return quadrature_encoder_decode(A, B)

def get_error(position, desired_position):
    return desired_position - position

def adjust_step_delay(error, Kp):
    return 1 / (Kp * np.abs(error))

def main():
    # Set up encoder counters
    x_position = 0
    y_position = 0
    x_error = 0
    y_error = 0

    # Set up signal handler for SIGINT
    def signal_handler(sig, frame):
        GPIO.cleanup()
        raise KeyboardInterrupt

    signal.signal(signal.SIGINT, signal_handler)

    while True:
        try:
            command = input("Enter command (move x y, scan, set_scan, origin, pos, exit): ")
            if command == "exit":
                break
            elif command.startswith("move x"):
                direction = GPIO.HIGH if command[5] == 'F' else GPIO.LOW
                steps = int(command[5:])
                move_stepper(17, 18, steps, direction)
                x_position = get_encoder_position(22, 23)
                x_error = get_error(x_position, max_steps)
                x_position = min(max(x_position, 0), max_steps)
                y_position = get_encoder_position(24, 25)
                y_error = get_error(y_position, max_steps_y)
                y_position = min(max(y_position, 0), max_steps_y)
            elif command == "scan":
                for _ in range(steps_per_second):
                    x_position = get_encoder_position(22, 23)
                    y_position = get_encoder_position(24, 25)
                    x_error = get_error(x_position, max_steps)
                    y_error = get_error(y_position, max_steps_y)
                    x_position = min(max(x_position, 0), max_steps)
                    y_position = min(max(y_position, 0), max_steps_y)
                    print(f"X: {x_position}, Y: {y_position}, Error: {x_error}, {y_error}")
                    time.sleep(1 / steps_per_second)
            elif command == "set_scan":
                steps_per_second = int(input("Enter new scan speed: "))
                steps_per_second = min(max(steps_per_second, 1), 100)
            elif command == "origin":
                x_position = 0
                y_position = 0
            elif command == "pos":
                print(f"X: {x_position}, Y: {y_position}")
            else:
                print("Invalid command")
        except Exception as e:
            print(f"Error: {e}")

    GPIO.cleanup()

if __name__ == "__main__":
    main()

