    logger.error(f"Failed to create MQTT client: {e}")
    exit(1)

def read_dht_data():
    try:
        temperature = dht_device.temperature()
        humidity = dht_device.humidity()
        return temperature, humidity
    except RuntimeError as e:
        logger.error(f"Failed to read DHT22 sensor: {e}")
        return None, None

def publish_dht_data(temperature, humidity):
    try:
        timestamp = datetime.datetime.now().isoformat()
        message = f"{timestamp} Temp: {temperature:.1f}°C Humidity: {humidity:.1f}%"
        client.publish("dht22_sensor", message)
    except MQTTClientException as e:
        logger.error(f"Failed to publish to MQTT: {e}")

def main():
    global client
    try:
        while True:
            temperature, humidity = read_dht_data()
            if temperature is not None and humidity is not None:
                publish_dht_data(temperature, humidity)
            time.sleep(2)
    except KeyboardInterrupt:
        logger.info("Received KeyboardInterrupt, exiting cleanly")
    except CPUTimeoutError:
        logger.info("Timeout error, exiting cleanly")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        if client is not None:
            client.disconnect()
        dht_device.deinit()
        logger.info("Cleanly shut down")

if __name__ == "__main__":
