# Set up logging
log_dir = '/var/log/wearable'
if not os.path.exists(log_dir):
    log_dir = os.path.join(os.path.expanduser('~'), '.local', 'log', 'wearable')

log_file = os.path.join(log_dir, 'wearable.log')
if not os.path.exists(log_dir):
    os.makedirs(log_dir)

logging.basicConfig(
    format='%(asctime)s - %(levelname)s - %(message)s',
    level=logging.INFO,
    handlers=[
        logging.handlers.TimedRotatingFileHandler(log_file, when='midnight', backupCount=7),
        logging.StreamHandler(sys.stdout)
    ]
)

def validate_data(temperature, humidity):
    try:
        temperature = float(temperature)
        humidity = float(humidity)
        return 10 <= temperature <= 55 and 20 <= humidity <= 100
    except (TypeError, ValueError):
        return False

def simulate_dht22_sensor():
    while True:
        try:
            # Simulate sensor reading
            temperature = round(random.uniform(15, 45), 2)
            humidity = round(random.uniform(40, 95), 2)
            if validate_data(temperature, humidity):
                logging.info(f'Temperature: {temperature}°C, Humidity: {humidity}%')
            else:
                logging.error(f'Invalid data: Temperature={temperature}°C, Humidity={humidity}%')
        except Exception as e:
            logging.error(f'Error: {e}')
        time.sleep(5)

def main():
    try:
        # Initialize GPIO pin as a digital input
        gpio = gpiozero.CircuitPythonGPIO4()

        # Initialize MQTT client
        client = mqtt.Client()
        client.connect('localhost', 1883)

        # Start simulating sensor readings
        threading.Thread(target=simulate_dht22_sensor).start()

        while True:
            try:
                # Simulate sensor reading
                temperature = round(random.uniform(15, 45), 2)
                humidity = round(random.uniform(40, 95), 2)
                if validate_data(temperature, humidity):
                    client.publish('home/temperature', temperature)
                    client.publish('home/humidity', humidity)
                else:
                    logging.error(f'Invalid data: Temperature={temperature}°C, Humidity={humidity}%')
            except (KeyboardInterrupt, SystemExit):
                logging.info('Shutdown event detected')
                break
            except Exception as e:
                logging.error(f'Error: {e}')
            finally:
                # Close MQTT client
                client.disconnect()
                # Release GPIO pin
                gpio.close()

    except (KeyboardInterrupt, SystemExit):
        logging.info('Shutdown event detected')
    except Exception as e:
        logging.error(f'Error: {e}')

if __name__ == '__main__':
