import logging
import signal
import time
import logging.config
from gpiozero import MotionSensor
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
from paho.mqtt.client import MQTTClient
import iso8601

class SolarArrayMonitor:
    def __init__(self, sensor_pin=17, debouncing_interval=2.0, mqtt_broker='localhost', mqtt_port=1883, mqtt_topic='solar_array/occupancy'):
        self.sensor_pin = sensor_pin
        self.debounce_interval = debouncing_interval
        self.mqtt_broker = mqtt_broker
        self.mqtt_port = mqtt_port
        self.mqtt_topic = mqtt_topic
        self.sensor = None
        self.mqtt_client = None
        self.occupancy_events = []
        self.poll_interval = 0.5
        self.poll_count = 0
        self.total_events = 0
        self.logger = logging.getLogger(__name__)
        logging.config.dictConfig({
            'version': 1,
            'formatters': {
                'default': {
                    'format': '[%(asctime)s] %(levelname)s in %(module)s: %(message)s',
                }
            },
            'handlers': {
                'console': {
                    'class': 'logging.StreamHandler',
                    'formatter': 'default',
                    'level': 'INFO'
                }
            },
            'root': {
                'level': 'INFO',
                'handlers': ['console']
            }
        })

    def __del__(self):
        if self.sensor:
            self.sensor.close()
        if self.mqtt_client:
            self.mqtt_client.disconnect()

    def _init_sensor(self):
        try:
            self.sensor = MotionSensor(self.sensor_pin, pin_factory=self._get_pin_factory())
            self.sensor.bounce_time = self.debounce_interval
        except Exception as e:
            self.logger.error(f"Failed to initialize sensor: {e}")
            raise SystemExit(1)

    def _get_pin_factory(self):
        try:
            from gpiozero import PiGPIOFactory
            return PiGPIOFactory()
        except ImportError:
            from gpiozero import MockGPIOFactory
            return MockGPIOFactory()

    def _init_mqtt(self):
        try:
            self.mqtt_client = MQTTClient(self.mqtt_broker, self.mqtt_port)
            self.mqtt_client.connect()
            self.mqtt_client.subscribe(self.mqtt_topic)
        except Exception as e:
            self.logger.error(f"Failed to initialize MQTT client: {e}")
            raise SystemExit(1)

    def _handle_mqtt_message(self, client, userdata, message):
        try:
            event = iso8601.parse_date(message.payload.decode('utf-8'))
            self.occupancy_events.append(event)
            self.total_events += 1
            self.logger.info(f"Occupancy event detected at {event}")
        except Exception as e:
            self.logger.error(f"Failed to parse MQTT message: {e}")

    def start(self):
        try:
            self._init_sensor()
            self._init_mqtt()
            while True:
                try:
                    self.poll()
                except KeyboardInterrupt:
                    self.logger.info("Received SIGINT, exiting...")
                    break
                except Exception as e:
                    self.logger.error(f"Unexpected error: {e}")
                    break
            self.logger.info("Exiting cleanly...")
        except SystemExit:
            pass
        finally:
            self._del_sensor()
            self._del_mqtt()

    def poll(self):
        try:
            self.sensor.wait_for_edge('rising', timeout=self.poll_interval)
            self.poll_count += 1
            if self.poll_count % 10 == 0:
                self._publish_occupancy_report()
        except Exception as e:
            self.logger.error(f"Unexpected error: {e}")

    def _publish_occupancy_report(self):
