class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = Input(clk_pin, pull_up=True, min_edge_time=20)
        self.dt_pin = Input(dt_pin, pull_up=True, min_edge_time=20)
        self.callback = callback
        self.counter = 0
        self.prev_state = (self.clk_pin.value, self.dt_pin.value)
        self.clk_pin.on_edge = self.on_clk_edge
        self.dt_pin.on_edge = self.on_dt_edge

    def on_clk_edge(self, *args):
        try:
            self._update_counter()
        except Exception as e:
            logger.error(f"Error on CLK edge: {e}")

    def on_dt_edge(self, *args):
        try:
            self._update_counter()
        except Exception as e:
            logger.error(f"Error on DT edge: {e}")

    def _update_counter(self):
        current_state = (self.clk_pin.value, self.dt_pin.value)
        if current_state != self.prev_state:
            if current_state == (True, False):
                self.counter += 1
            elif current_state == (False, True):
                self.counter -= 1
            self.prev_state = current_state
            if self.callback:
                self.callback(self.counter)

    def cleanup(self):
        self.clk_pin.off()
        self.dt_pin.off()
        self.clk_pin.remove_event_listener(self.on_clk_edge)
        self.dt_pin.remove_event_listener(self.on_dt_edge)

