            logger.error(f"Error on CLK edge: {e}")

    def on_dt_edge(self, *args):
        try:
            self._update_counter()
        except Exception as e:
            logger.error(f"Error on DT edge: {e}")

    def _update_counter(self):
        current_state = (self.clk_pin.value, self.dt_pin.value)
        if current_state != self.prev_state:
            if current_state == (True, False):
                self.counter += 1
            elif current_state == (False, True):
                self.counter -= 1
            self.prev_state = current_state
            if self.callback:
                self.callback(self.counter)

    def cleanup(self):
        self.clk_pin.off()
        self.dt_pin.off()
        self.clk_pin.remove_event_listener(self.on_clk_edge)
        self.dt_pin.remove_event_listener(self.on_dt_edge)

def main():
    try:
        clk_pin = 17
        dt_pin = 18
        callback = None  # Optional callback function

        encoder = RotaryEncoder(clk_pin, dt_pin, callback)

        while True:
            try:
                time.sleep(0.1)
                if encoder.counter != 0:
                    logger.info(f"Counter: {encoder.counter}")
            except KeyboardInterrupt:
                break
            except Exception as e:
                logger.error(f"Error: {e}")

        encoder.cleanup()
    except Exception as e:
        logger.error(f"Error: {e}")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, main)
    signal.signal(signal.SIGTERM, main)
    main()
```

This code defines a `RotaryEncoder` class that interfaces a rotary encoder using the gpiozero library. It detects rising and falling edges on both CLK and DT pins, maintains an internal integer counter, and invokes a user-supplied callback with the new counter value. The `cleanup` method releases GPIO resources and removes event listeners. The `main` function instantiates the encoder, prints counter changes, and runs until interrupted. It also catches and logs any I/O or runtime errors without crashing the program.

