import logging
import threading
import time
import signal
import sys
import gpiozero
import picamera2
from adafruit_circuitpython_mcp3008 import MCP3008
from adafruit_circuitpython_trigecho import TRIG_ECHO
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(filename='parking_sensor.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SAFE_DISTANCE = 150
WARNING_DISTANCE = 75
CRITICAL_DISTANCE = 30
SENSOR_A_TRIG = 17
SENOR_A_ECHO = 27
SENOR_B_TRIG = 22
SENOR_B_ECHO = 23
CALIBRATION_READINGS = 10
CALIBRATION_WINDOW = 0.05
MEASUREMENT_READINGS = 5
MEASUREMENT_WINDOW = 0.2
SIMULATION = False

class ParkingSensor:
    def __init__(self, trig, echo, sensor_name):
        self.trig = gpiozero.CircuitPythonTRIG_ECHO(trig, echo, self._measure_distance)
        self.sensor_name = sensor_name

    def _measure_distance(self):
        try:
            self.trig.send_trigger()
            start_time = time.time()
            while True:
                if time.time() - start_time > 0.03:
                    return (time.time() - start_time) * 29.92
        except Exception as e:
            logging.error(f"Error measuring distance with {self.sensor_name}: {e}")
            return None

    def get_distance(self):
        return self._measure_distance()

class ParkingSystem:
    def __init__(self):
        self.sensor_a = ParkingSensor(SENOR_A_TRIG, SENOR_A_ECHO, "Sensor A")
        self.sensor_b = ParkingSensor(SENOR_B_TRIG, SENOR_B_ECHO, "Sensor B")
        self.calibrated_sensors = {}
        self.mqtt_client = MQTTClient()
        self.mqtt_client.connect("localhost", 1883)
        self.mqtt_client.subscribe("parking_sensor")

    def calibrate_sensors(self):
        for sensor in [self.sensor_a, self.sensor_b]:
            readings = [sensor.get_distance() for _ in range(CALIBRATION_READINGS)]
            self.calibrated_sensors[sensor.sensor_name] = sum(readings) / CALIBRATION_READINGS

    def measure_distance(self):
        for sensor in [self.sensor_a, self.sensor_b]:
            distance = sensor.get_distance()
            if distance is None:
                return None
            distance -= self.calibrated_sensors[sensor.sensor_name]
            if SIMULATION:
                distance = distance * 2
            return distance

    def monitor(self):
        while True:
            distances = [self.measure_distance() for _ in range(MEASUREMENT_READINGS)]
            median_distance = sorted(distances)[MEASUREMENT_READINGS // 2]
            if median_distance is None:
                logging.warning(f"No distance readings from any sensor")
                continue
            median_distance -= self.calibrated_sensors[list(distances)[0]]
            if SIMULATION:
                median_distance = median_distance * 2
            if median_distance < CRITICAL_DISTANCE:
                logging.info(f"CRITICAL: {self.sensor_a.sensor_name} distance: {median_distance:.2f} cm")
                # Activate actuator
            elif median_distance < WARNING_DISTANCE:
                logging.warning(f"WARNING: {self.sensor_a.sensor_name} distance: {median_distance:.2f} cm")
                # Activate actuator
            elif median_distance < SAFE_DISTANCE:
                logging.info(f"SAFE: {self.sensor_a.sensor_name} distance: {median_distance:.2f} cm")
                # Activate actuator
            else:
                logging.info(f"OK: {self.sensor_a.sensor_name} distance: {median_distance:.2f} cm")
            time.sleep(MEASUREMENT_WINDOW)

    def start(self):
        self.calibrate_sensors()
        threading.Thread(target=self.monitor).start()

def signal_handler(sig, frame):
    logging.info("SIGINT received, shutting down")
    self.mqtt_client.disconnect()
    for sensor in [self.sensor_a, self.sensor_b]:
        sensor.trig.stop()
    sys.exit(0)

def main():
    global SIMULATION
    if SIMULATION:
        SIMULATION = True
        logging.info("SIMULATION MODE ACTIVATED")
    else:
        try:
            sensor_a = gpiozero.CircuitPythonTRIG_ECHO(SENOR_A_TRIG, SENOR_A_ECHO, ParkingSensor._measure_distance)
            sensor_b = gpiozero.CircuitPythonTRIG_ECHO(SENOR_B_TRIG, SENOR_B_ECHO, ParkingSensor._measure_distance)
        except Exception as e:
            logging.error(f"Error initializing sensors: {e}")
            sys.exit(1)
    parking_system = ParkingSystem()
    parking_system.start()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("SIGINT received, shutting down")
        parking_system.mqtt_client.disconnect()
        for sensor in [parking_system.sensor_a, parking_system.sensor_b]:
            sensor.trig.stop()
        sys.exit(0)

if __name__ == "__main__":
    main()

