client = mqtt.Client()
client.connect("localhost", 1883)

# Set up sensor addresses
addresses = [0x3B, 0x3C, 0x3D]

# Set up sensor data
data = {
    "active_power": [0, 0, 0],
    "voltage": [0, 0, 0],
    "current": [0, 0, 0],
    "frequency": [0, 0, 0],
    "power_factor": [0, 0, 0],
}

# Set up log file
log_file = "energy_log_2023-09-11.json"
log_lock = Lock()

def simulate_sensor_data():
    while True:
        try:
            # Simulate sensor data
            for i, address in enumerate(addresses):
                data["active_power"][i] = round((i * 10) % 150 + 50, 2)
                data["voltage"][i] = round((i * 10) % 20 + 220, 2)
                data["current"][i] = round((i * 10) % 1 + 0.2, 2)
                data["frequency"][i] = round((i * 10) % 1.5 + 59.5, 2)
                data["power_factor"][i] = round((i * 10) % 0.2 + 0.8, 2)

            # Create log file if it doesn't exist
            if not os.path.exists(log_file):
                with open(log_file, "w") as f:
                    pass

            # Append data to log file
            with log_lock:
                with open(log_file, "a") as f:
                    json.dump(data, f)
                    f.write("\n")

            # Check if log file size exceeds 1 MB
            if os.path.getsize(log_file) > 1024 * 1024:
                # Compress log file
                try:
                    with log_lock:
                        with open(log_file, "rb") as f_in, gzip.open(log_file + ".gz", "wb") as f_out:
                            shutil.copyfileobj(f_in, f_out)
                    os.remove(log_file)
                    log_file = log_file + ".gz"
                except Exception as e:
                    logger.error(f"Error compressing log file: {e}")

            # Rotate log file
            try:
                if os.path.getsize(log_file) > 10 * 1024 * 1024:  # 10 MB
                    os.rename(log_file, log_file + ".old")
            except Exception as e:
                logger.error(f"Error rotating log file: {e}")

        except Exception as e:
            logger.error(f"Error acquiring sensor data: {e}")
            break

        # Sleep for 5 seconds
        time.sleep(5)

