    try:
        with open(log_file, "r") as f:
            data = json.load(f)
            for i, reading in enumerate(data):
                print(f"Sensor {i}: active_power={reading['active_power']}, voltage={reading['voltage']}, current={reading['current']}, frequency={reading['frequency']}, power_factor={reading['power_factor']}")
    except Exception as e:
        logger.error(f"Error viewing readings: {e}")

def view_data(date):
    try:
        with open(log_file, "r") as f:
            data = json.load(f)
            for i, reading in enumerate(data):
                if datetime.strptime(reading["timestamp"], "%Y-%m-%d %H:%M:%S") == datetime.strptime(date, "%Y-%m-%d"):
                    print(f"Sensor {i}: active_power={reading['active_power']}, voltage={reading['voltage']}, current={reading['current']}, frequency={reading['frequency']}, power_factor={reading['power_factor']}")
    except Exception as e:
        logger.error(f"Error viewing data for {date}: {e}")

def min_max_avg_power(sensor, date):
    try:
        with open(log_file, "r") as f:
            data = json.load(f)
            for i, reading in enumerate(data):
                if datetime.strptime(reading["timestamp"], "%Y-%m-%d %H:%M:%S") == datetime.strptime(date, "%Y-%m-%d"):
                    if sensor == "active_power":
                        return min(reading["active_power"], key=min), max(reading["active_power"]), sum(reading["active_power"]) / len(data)
                    elif sensor == "voltage":
                        return min(reading["voltage"], key=min), max(reading["voltage"]), sum(reading["voltage"]) / len(data)
                    elif sensor == "current":
                        return min(reading["current"], key=min), max(reading["current"]), sum(reading["current"]) / len(data)
                    elif sensor == "frequency":
                        return min(reading["frequency"], key=min), max(reading["frequency"]), sum(reading["frequency"]) / len(data)
                    elif sensor == "power_factor":
                        return min(reading["power_factor"], key=min), max(reading["power_factor"]), sum(reading["power_factor"]) / len(data)
    except Exception as e:
        logger.error(f"Error calculating min/max/avg {sensor} for {date}: {e}")

def main():
    try:
        # Start sensor data acquisition thread
        threading.Thread(target=simulate_sensor_data).start()

        while True:
            print("1. View current readings")
            print("2. View data for a given date")
            print("3. Display minimum/maximum/average active power for a given sensor and date")
            print("4. Quit")
            choice = input("Enter your choice: ")

            if choice == "1":
                view_readings()
            elif choice == "2":
                date = input("Enter date (YYYY-MM-DD): ")
                view_data(date)
            elif choice == "3":
                sensor = input("Enter sensor (active_power, voltage, current, frequency, power_factor): ")
                date = input("Enter date (YYYY-MM-DD): ")
                min_val, max_val, avg_val = min_max_avg_power(sensor, date)
                print(f"{sensor}: min={min_val}, max={max_val}, avg={avg_val}")
            elif choice == "4":
                break
            else:
                print("Invalid choice")

    except Exception as e:
        logger.error(f"Error in main: {e}")

    # Stop sensor data acquisition thread
    simulate_sensor_data()

if __name__ == "__main__":
    main()

