import argparse
import logging
import smbus2
import picamera2
import picamera2.array
import time
import json
import csv
import signal
import sys
import io
import threading
from contextlib import contextmanager

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define constants
ANOMALY_THRESHOLD = 50  # deg/s^2
Sensitivity = 131.0  # LSB/(deg/s)
GYRO_REG_XOUT_H = 0x43
GYRO_REG_YOUT_H = 0x45
GYRO_REG_ZOUT_H = 0x47
BUS_ADDRESS = 0x68
BUS_SPEED = 100000  # I2C bus speed

# Define signal handlers
def signal_handler(sig, frame):
    logger.info("Received signal %s, exiting...", sig)
    sys.exit(0)

def cleanup():
    logger.info("Cleaning up...")
    # Release I2C bus
    try:
        with smbus2.SMBus(bus=1) as bus:
            bus.close()
    except smbus2.SMBusError as e:
        logger.critical("Failed to release I2C bus: %s", e)
    # Release camera
    try:
        camera = picamera2.PiCamera()
        camera.close()
    except AttributeError:
        pass
    # Release CSV file
    try:
        with open("gyro_data.csv", "w", newline="") as csvfile:
            pass
    except IOError as e:
        logger.critical("Failed to release CSV file: %s", e)
    # Release JSON file
    try:
        with open("gyro_data.json", "w") as jsonfile:
            pass
    except IOError as e:
        logger.critical("Failed to release JSON file: %s", e)
    sys.exit(0)

# Define the main function
def main():
    # Parse command-line arguments
    parser = argparse.ArgumentParser(description="Reads data from an MPU-6050 gyroscope over I2C bus 1")
    parser.add_argument("--sample_rate", type=int, default=10, help="Sample rate in Hz")
    parser.add_argument("--window_size", type=int, default=5, help="Window size for moving-average filter")
    parser.add_argument("--cloud_enabled", action="store_true", help="Enable cloud logging")
    parser.add_argument("--cloud_url", type=str, default="", help="Cloud logging URL")
    args = parser.parse_args()

    # Set up signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Set up I2C bus
    try:
        with smbus2.SMBus(bus=1) as bus:
            bus.set_speed(BUS_SPEED)
    except smbus2.SMBusError as e:
        logger.critical("Failed to initialize I2C bus: %s", e)
        return

    # Set up camera
    try:
        camera = picamera2.PiCamera()
        camera.resolution = (640, 480)
        camera.framerate = args.sample_rate
    except AttributeError:
        logger.critical("Failed to initialize camera")
        return

    # Set up CSV and JSON files
    try:
        with open("gyro_data.csv", "w", newline="") as csvfile:
            writer = csv.writer(csvfile)
        with open("gyro_data.json", "w") as jsonfile:
            jsonfile.write("")
    except IOError as e:
        logger.critical("Failed to create CSV and JSON files: %s", e)
        return

    # Set up moving-average filter
    def moving_average(data, window_size):
        window = []
        for i in range(len(data)):
            window.append(data[i])
            if i >= window_size:
                window.pop(0)
            if i >= window_size - 1:
                yield sum(window) / window_size

    # Set up anomaly detection
    def detect_anomaly(data):
        rate = []
        for i in range(1, len(data)):
            rate.append((data[i] - data[i-1]) / (i - (i-1)))
        return any(abs(x) > ANOMALY_THRESHOLD for x in rate)

    # Main loop
    with contextmanager(io.StringIO()) as f:
        with open(f.name, "w", newline="") as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["timestamp", "raw_x", "raw_y", "raw_z", "filtered_x", "filtered_y", "filtered_z", "anomaly"])
            start_time = time.time()
            while True:
                try:
                    # Read gyroscope data
                    with smbus2.SMBus(bus=1) as bus:
                        xout_h = bus.read_byte(GYRO_REG_XOUT_H)
                        yout_h = bus.read_byte(GYRO_REG_YOUT_H)
                        zout_h = bus.read_byte(GYRO_REG_ZOUT_H)
                        xout_l = bus.read_byte(GYRO_REG_XOUT_L)
                        yout_l = bus.read_byte(GYRO_REG_YOUT_L)
                        zout_l = bus.read_byte(GYRO_REG_ZOUT_H)

                    # Convert raw data to degrees per second
                    x = (xout_h << 8 | xout_l) * Sensitivity
                    y = (yout_h << 8 | yout_l) * Sensitivity
                    z = (zout_h << 8 | zout_l) * Sensitivity

                    # Apply moving-average filter
