# Define constants
ANOMALY_THRESHOLD = 50  # deg/s^2
Sensitivity = 131.0  # LSB/(deg/s)
GYRO_REG_XOUT_H = 0x43
GYRO_REG_YOUT_H = 0x45
GYRO_REG_ZOUT_H = 0x47
BUS_ADDRESS = 0x68
BUS_SPEED = 100000  # I2C bus speed

# Define signal handlers
def signal_handler(sig, frame):
    logger.info("Received signal %s, exiting...", sig)
    sys.exit(0)

def cleanup():
