# Define the main function
def main():
    # Parse command-line arguments
    parser = argparse.ArgumentParser(description="Reads data from an MPU-6050 gyroscope over I2C bus 1")
    parser.add_argument("--sample_rate", type=int, default=10, help="Sample rate in Hz")
    parser.add_argument("--window_size", type=int, default=5, help="Window size for moving-average filter")
    parser.add_argument("--cloud_enabled", action="store_true", help="Enable cloud logging")
    parser.add_argument("--cloud_url", type=str, default="", help="Cloud logging URL")
    args = parser.parse_args()

    # Set up signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Set up I2C bus
    try:
        with smbus2.SMBus(bus=1) as bus:
            bus.set_speed(BUS_SPEED)
    except smbus2.SMBusError as e:
        logger.critical("Failed to initialize I2C bus: %s", e)
        return

    # Set up camera
