import busio
import adafruit_tcs34725
from adafruit_tcs34725 import TCS34725
from PIL import Image
import io
import signal
import logging
import time
import os

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define signal handlers
def signal_handler(sig, frame):
    logger.info("Received signal, shutting down...")
    try:
        i2c_bus.close()
    except AttributeError:
        pass
    finally:
        exit(0)

def main():
    # Initialize I2C bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except OSError as e:
        logger.error(f"I2C bus initialization failed: {e}")
        return

    # Initialize TCS34725 sensor
    try:
        sensor = TCS34725(i2c_bus, address=0x29)
    except OSError as e:
        logger.error(f"TCS34725 sensor initialization failed: {e}")
        return

    # Set sensor integration time and gain
    sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
    sensor.gain = adafruit_tcs34725.GAIN_4X

    # Define function to get sensor color data
    def get_sensor_color_data():
        try:
            color_rgb_bytes = sensor.color
            return (color_rgb_bytes[0], color_rgb_bytes[1], color_rgb_bytes[2], color_rgb_bytes[3])
        except Exception as e:
            logger.error(f"Error reading sensor color data: {e}")
            return (0, 0, 0, 0)

    # Define function to find dominant image color
    def find_dominant_image_color(image_path):
        try:
            with Image.open(image_path) as img:
                img = img.resize((100, 100))
                pixels = img.getdata()
                colors = [pixel for pixel in pixels]
                return max(set(colors), key=colors.count)
        except FileNotFoundError:
            logger.error("File not found")
            return (0, 0, 0)
        except Exception as e:
            logger.error(f"Error reading image: {e}")
            return (0, 0, 0)

    # Main loop
    while True:
        try:
            sensor_color = get_sensor_color_data()
            dominant_color = find_dominant_image_color('image.jpg')
            logger.info(f"Sensor color: {sensor_color}, Dominant image color: {dominant_color}")
            time.sleep(1)
        except KeyboardInterrupt:
            logger.info("Received KeyboardInterrupt, shutting down...")
            break
        except Exception as e:
            logger.error(f"Error in main loop: {e}")
            break

    # Clean up
    try:
        i2c_bus.close()
    except AttributeError:
        pass

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)
    main()

