import logging
import socket
import time
import signal
import smbus2
import serial
import json
from gpiozero import CPUTimeoutError
from adafruit_gps.adafruit_gps import GPSDevice
from adafruit_gps.exceptions import GPSException
from adafruit_circuitpython_mma8451 import MMA8451
from adafruit_circuitpython_mpu6050 import MPU6050
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Set up signal handlers
def signal_handler(sig, frame):
    logger.info('Received signal %s, shutting down', sig)
    sys.exit(0)

def main():
    # Initialize signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Set up MQTT client
    mqtt_client = MQTTClient('wildlife_tracker', 'localhost', 1883)
    mqtt_client.connect()

    # Set up GPS module
    try:
        gps_device = GPSDevice()
    except (ImportError, GPSException):
        logger.error('Failed to import GPS module, falling back to simulated coordinates')
        gps_device = SimulatedGPS()

    # Set up serial connection
    try:
        serial_device = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except (OSError, serial.SerialException):
        logger.error('Failed to open serial connection, falling back to simulated coordinates')
        serial_device = SimulatedSerial()

    # Set up GPIO
    try:
        mma8451 = MMA8451()
        mpu6050 = MPU6050()
    except (ImportError, Exception):
        logger.error('Failed to import sensor modules, falling back to simulated data')
        mma8451 = SimulatedMMA8451()
        mpu6050 = SimulatedMPU6051()

    # Set up socket
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.bind(('127.0.0.1', 9099))
        sock.listen(1)
    except (OSError, socket.error):
        logger.error('Failed to bind socket, exiting')
        return

    while True:
        try:
            # Accept incoming connection
            conn, addr = sock.accept()
            logger.info('Connection from %s', addr)

            # Handle command
            try:
                data = conn.recv(1024)
                if not data:
                    logger.error('No data received, closing connection')
                    conn.close()
                    continue

                command = data.decode('utf-8')
                if command == 'start':
                    gps_device.start()
                    mma8451.start()
                    mpu6050.start()
                    logger.info('Tracking started')
                elif command == 'stop':
                    gps_device.stop()
                    mma8451.stop()
                    mpu6051.stop()
                    logger.info('Tracking stopped')
                elif command == 'report':
                    try:
                        position = gps_device.read_position()
                        if position is None:
                            logger.error('Failed to read GPS position')
                            conn.sendall(b'{"error": "GPS position not available"}')
                        else:
                            conn.sendall(json.dumps(position).encode('utf-8'))
                    except (GPSException, Exception) as e:
                        logger.error('Failed to read GPS position: %s', e)
                        conn.sendall(b'{"error": "GPS position not available"}')
                else:
                    logger.error('Invalid command: %s', command)
                    conn.sendall(b'{"error": "Invalid command"}')
            except (ConnectionResetError, socket.error):
                logger.error('Connection reset or error, closing connection')
            finally:
                conn.close()
        except (ConnectionResetError, socket.error):
            logger.error('Connection reset or error, continuing')
        except (TimeoutError, CPUTimeoutError):
            logger.error('Timeout or CPU error, continuing')

if __name__ == '__main__':
    main()
