import pigpio
import time
from gpiozero import PWMOutput
from adafruit_circuitpython_mcp3008 import MCP3008
from paho.mqtt.client import MQTTClient

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi, pin):
        self.pi = pi
        self.pin = pin
        self.pwm = PWMOutput(self.pi, self.pin, initial_duty=0, frequency=1000)
        self.mcp3008 = MCP3008(pigpio.pi, 0, 1)  # Assuming ADC pin 1 for voltage sensing

    def set_frequency(self, freq):
        try:
            self.pwm.frequency(freq)
        except pigpio.Error as e:
            raise MotorError(f"Failed to set PWM frequency: {e}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be an integer in the range 0-255")
        try:
            self.pwm.duty_cycle(duty)
        except pigpio.Error as e:
            raise MotorError(f"Failed to set PWM duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        self.pwm.close()
        self.pi.stop()

    def close(self):
        self.stop()
        self.pi.stop()
        self.pi.close()

def main():
    try:
        pi = pigpio.pi()
        motor = Motor(pi, 18)  # Replace 18 with your desired GPIO pin
        motor.set_frequency(1000)
        motor.set_duty_cycle(128)
        time.sleep(1)
        motor.set_duty_cycle(0)
        motor.stop()
    except MotorError as e:
        print(f"MotorError: {e}")
    except pigpio.Error as e:
        print(f"pigpio Error: {e}")
    finally:
        motor.close()

if __name__ == "__main__":
    main()

