from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define Modbus register map
CONTROL = {
    'R': {'Register': 0x3100, 'functioncode': 3},
    'W': {'Register': 0x3100, 'functioncode': 6, 'Value': {'Stop': 0x0006, 'Start': 0x000F}}
}
STATUS = {
    'R': {'Register': 0x3000, 'functioncode': 3},
    'W': {'Register': 0x3000, 'functioncode': 16}
}
OPMODE = {
    'W': {'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1}}
}
VELOCITYFEEDBACK = {
    'R': {'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
    'W': {'Register': 0x3B00, 'functioncode': 16}
}
POSITIONFEEDBACK = {
    'R': {'Register': 0x3700, 'functioncode': 3, 'read_length': 2},
    'W': {'Register': 0x3700, 'functioncode': 16}
}
POSITIONCOMMAND = {
    'R': {'Register': 0x4000, 'functioncode': 3},
    'W': {'Register': 0x4000, 'functioncode': 16}
}
VELOCITYCOMMAND = {
    'R': {'Register': 0x6F00, 'functioncode': 3},
    'W': {'Register': 0x6F00, 'functioncode': 16}
}

class Servo:
    def __init__(self, serial_port='/dev/serial0', baudrate=115200, timeout=1):
        self.serial = serial.Serial(serial_port, baudrate, timeout=timeout)
        self.modbus = ModbusMaster(serial_port, timeout=timeout)
        self.mqtt_client = MQTTClient('servo', 'localhost', 1883)
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_publish = self.on_publish
        self.mqtt_client.on_disconnect = self.on_disconnect
        self.mqtt_client.connect()
        self.mqtt_client.subscribe('servo/velocity', 0)

    def on_connect(self, client, userdata, flags, rc):
        logger.info('Connected to MQTT broker')
        self.mqtt_client.publish('servo/velocity', '0')

    def on_publish(self, client, userdata, mid):
        pass

    def on_disconnect(self, client, userdata, rc):
        logger.info('Disconnected from MQTT broker')
        self.mqtt_client.disconnect()

    def read(self, register, functioncode):
        try:
            response = self.modbus.read_holding_registers(register['Register'], register['functioncode'], unit=1)
            if response is None:
                raise CPUTimeoutError('Timeout reading register')
            return response.registers
        except serial.SerialException as e:
            logger.error(f'Error reading register {register["Register"]}: {e}')
            return None
        except ModbusException as e:
            logger.error(f'Error reading register {register["Register"]}: {e}')
            return None

    def write(self, register, functioncode, value):
        try:
            self.modbus.write_single_holding_register(register['Register'], value, register['functioncode'], unit=1)
        except serial.SerialException as e:
            logger.error(f'Error writing to register {register["Register"]}: {e}')
        except ModbusException as e:
            logger.error(f'Error writing to register {register["Register"]}: {e}')

    def get_status(self):
        return self.read(STATUS, 'R')

    def set_control(self, value):
        self.write(CONTROL, 'W', value)

    def set_opmode(self, value):
        self.write(OPMODE, 'W', value)

    def get_velocity_feedback(self):
        return self.read(VELOCITYFEEDBACK, 'R')

    def set_position_command(self, value):
        self.write(POSITIONCOMMAND, 'W', value)

    def get_position_feedback(self):
        return self.read(POSITIONFEEDBACK, 'R')

    def get_velocity_command(self):
        return self.read(VELOCITYCOMMAND, 'R')

    def run(self):
        while True:
            try:
                self.mqtt_client.publish('servo/velocity', str(self.get_velocity_feedback()['registers'][0]))
                time.sleep(1)
            except Exception as e:
                logger.error(f'Error running servo loop: {e}')

def signal_handler(sig, frame):
    logger.info('Received signal to exit')
    if hasattr(Servo, 'serial'):
        Servo.serial.close()
    if hasattr(Servo, 'modbus'):
        Servo.modbus.close()
    if hasattr(Servo, 'mqtt_client'):
        Servo.mqtt_client.disconnect()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    try:
        servo = Servo()
        servo.run()
    except Exception as e:
        logger.error(f'Error initializing servo: {e}')

