import logging
import signal
import sys
import time
import serial
from minimalmodbus import ModbusRtuMaster
from gpiozero import CPUTimer
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008

class ServoMotor:
    def __init__(self, serial_port, baudrate=115200, slave_address=1):
        self.serial_port = serial_port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.modbus = None
        self.timer = None
        self.camera = None
        self.mcp3008 = None
        self.error = None

    def _open_serial(self):
        try:
            self.serial = serial.Serial(self.serial_port, self.baudrate, timeout=1)
            self.serial.setParity(serial.PARITY_NONE)
            self.serial.bytesize = serial.EIGHTBITS
            self.serial.parity = serial.PARITY_NONE
            self.serial.stopbits = serial.STOPBITS_ONE
            self.serial.timeout = 1
            self.serial.close()
            self.serial = serial.Serial(self.serial_port, self.baudrate, timeout=1)
        except serial.SerialException as e:
            self.error = f"Failed to open serial port: {e}"
            return False
        return True

    def _close_serial(self):
        if self.serial:
            self.serial.close()
            self.serial = None

    def _open_modbus(self):
        try:
            self.modbus = ModbusRtuMaster(self.serial, self.slave_address)
        except Exception as e:
            self.error = f"Failed to open Modbus: {e}"
            return False
        return True

    def _close_modbus(self):
        if self.modbus:
            self.modbus.close()
            self.modbus = None

    def _open_mcp3008(self):
        try:
            self.mcp3008 = MCP3008()
        except Exception as e:
            self.error = f"Failed to open MCP3008: {e}"
            return False
        return True

    def _close_mcp3008(self):
        if self.mcp3008:
            self.mcp3008.close()
            self.mcp3008 = None

    def set_operation_mode(self, mode):
        if not self._open_serial():
            return self.error
        if not self._open_modbus():
            return self.error
        if not self._open_mcp3008():
            return self.error
        try:
            self.modbus.write_single_register(0x3500, mode)
        except Exception as e:
            self.error = f"Failed to set operation mode: {e}"
            self._close_serial()
            self._close_modbus()
            self._close_mcp3008()
            return self.error
        self._close_serial()
        self._close_modbus()
        self._close_mcp3008()
        return None

    def write_position_command(self, value):
        if not self._open_serial():
            return self.error
        if not self._open_modbus():
            return self.error
        if not self._open_mcp3008():
            return self.error
        try:
            self.modbus.write_single_register(0x4000, value)
        except Exception as e:
            self.error = f"Failed to write position command: {e}"
            self._close_serial()
            self._close_modbus()
            self._close_mcp3008()
            return self.error
        self._close_serial()
        self._close_modbus()
        self._close_mcp3008()
        return None

    def write_velocity_command(self, value):
        if not self._open_serial():
            return self.error
        if not self._open_modbus():
            return self.error
        if not self._open_mcp3008():
            return self.error
        try:
            self.modbus.write_single_register(0x6F00, value)
        except Exception as e:
            self.error = f"Failed to write velocity command: {e}"
            self._close_serial()
            self._close_modbus()
            self._close_mcp3008()
            return self.error
        self._close_serial()
        self._close_modbus()
        self._close_mcp3008()
        return None

    def read_position_feedback(self):
        if not self._open_serial():
            return self.error
        if not self._open_modbus():
            return self.error
