class DS1338RTC:
    def __init__(self, i2c_bus=1, i2c_address=0x68, century=21):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.century = century
        self.seconds = 0
        self.minutes = 0
        self.hours = 0
        self.date = 0
        self.month = 0
        self.year = 0
        self.i2c_handle = None

        self._init_i2c()

    def _init_i2c(self):
        try:
            self.i2c_handle = smbus2.SMBus(self.i2c_bus)
            self.i2c_handle.write_byte(self.i2c_address, 0x00)  # reset
