try:
    client = mqtt.Client()
except Exception as e:
    logger.error(f"Failed to initialize MQTT client: {e}")
    exit(1)

# Set up MCP3008 sensor
try:
    mcp3008 = MCP3008()
except Exception as e:
    logger.error(f"Failed to initialize MCP3008 sensor: {e}")
    exit(1)

def parse_gpgga(sentence):
    parts = sentence.split(',')
    if len(parts) < 8:
        return None
    return {
        'latitude': parts[1],
        'longitude': parts[2],
        'altitude': parts[3],
        'fix_quality': parts[7]
    }

def read_nmea(sentence):
    try:
        data = parse_gpgga(sentence)
        if data and data['fix_quality'] == '1':
            logger.info(f"GPS Fix: {data['latitude']}, {data['longitude']}, {data['altitude']}")
            return data
    except Exception as e:
        logger.error(f"Failed to parse NMEA sentence: {e}")
    return None

def main():
    while True:
        try:
            sentence = ser.readline().decode('utf-8').strip()
            if sentence.startswith('$GPGGA'):
                data = read_nmea(sentence)
                if data:
                    timestamp = datetime.now().isoformat()
                    logger.info(f"{timestamp} - {data['latitude']}, {data['longitude']}, {data['altitude']}")
                    client.publish('home/gps', f"{timestamp} - {data['latitude']}, {data['longitude']}, {data['altitude']}")
        except serial.SerialException as e:
            logger.error(f"Serial port error: {e}")
        except Exception as e:
            logger.error(f"Error: {e}")
        finally:
            time.sleep(1)

if __name__ == "__main__":
