import logging
import serial
from gpiozero import CPUTimeoutError
from dataclasses import dataclass
from datetime import datetime
from typing import Optional
import picamera2
from adafruit_circuitpython_mps401a import Mps401a
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int

class GPSReader:
    def __init__(self, port: str, baud: int):
        self.port = port
        self.baud = baud
        self.serial = None
        self.mps401a = None
        self.mqtt_client = None

    def connect(self):
        try:
            self.serial = serial.Serial(self.port, self.baud, timeout=1)
            self.mps401a = Mps401a()
            self.mqtt_client = MQTTClient()
            self.mqtt_client.connect("localhost", 1883)
            self.mqtt_client.subscribe("gps_data")
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {self.port}: {e}")
            return False
        except Exception as e:
            logger.error(f"Failed to initialize GPS reader: {e}")
            return False
        return True

    def disconnect(self):
        if self.serial is not None:
            self.serial.close()
            self.serial = None
        if self.mps401a is not None:
            self.mps401a.deinit()
            self.mps401a = None
        if self.mqtt_client is not None:
            self.mqtt_client.disconnect()
            self.mqtt_client = None

def parse_gpgga(sentence: str) -> Optional[GPS_readings]:
    parts = sentence.split(',')
    if len(parts) != 10:
        return None
    try:
        latitude = float(parts[1]) / 60 + float(parts[2]) / 100
        longitude = float(parts[3]) / 60 + float(parts[4]) / 100
        if parts[6] == 'S' and latitude < 0:
            latitude = -latitude
        elif parts[6] == 'N' and latitude > 0:
            latitude = -latitude
        if parts[11] == 'E' and longitude > 0:
            longitude = -longitude
        elif parts[11] == 'W' and longitude < 0:
            longitude = -longitude
        altitude = float(parts[9])
        satellites = int(parts[7])
        return GPS_readings(latitude, longitude, altitude, satellites)
    except (ValueError, IndexError) as e:
        logger.error(f"Failed to parse GPGGA sentence: {e}")
        return None

def main():
    gps_reader = GPSReader('/dev/serial0', 9600)
    if not gps_reader.connect():
        return

    try:
        while True:
            try:
                line = gps_reader.serial.readline()
                if line:
                    sentence = line.decode('utf-8').strip()
                    if sentence.startswith('$GPGGA'):
                        gps_readings = parse_gpgga(sentence)
                        if gps_readings is not None:
                            gps_reader.mqtt_client.publish("gps_data", str(gps_readings))
            except serial.SerialTimeoutException:
                logger.warning("Serial read timeout")
            except Exception as e:
                logger.error(f"Error reading from serial port: {e}")
    except KeyboardInterrupt:
        logger.info("Stopping GPS reader")
    except CPUTimeoutError:
        logger.info("CPU timeout")
    finally:
        gps_reader.disconnect()

if __name__ == "__main__":
    main()

