        self.serial_timeout = 5
        self.serial_buffer_size = 1024
        self.serial_baudrate = 115200
        self.signal_handler = self._signal_handler

    def _signal_handler(self, signum, frame):
        if self.serial_port:
            self.serial_port.close()
        exit()

