import time
import logging

class Sim28GPS:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.serial = None
        self._setup_logger()

    def _setup_logger(self):
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def __enter__(self):
        try:
            self.serial = serial.Serial(self.port, self.baud, timeout=1)
            self.serial.close()
            self.serial = serial.Serial(self.port, self.baud, timeout=1)
            self.serial.write(b'AT\r\n')
            self.serial.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            self.serial.write(b'AT\r\n')
            response = self.serial.readline()
            if response.startswith(b'+CGNSPWR: 1\r\n'):
                self.logger.info('GPS powered on')
            else:
                self.logger.error('Failed to power on GPS')
                raise Exception('Failed to power on GPS')
            return self
        except serial.SerialException as e:
            self.logger.error(f'Failed to open serial port: {e}')
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial is not None:
            try:
                self.serial.close()
            except serial.SerialException as e:
                self.logger.error(f'Failed to close serial port: {e}')

    def attach(self):
        try:
            self.serial.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            response = self.serial.readline()
            if response.startswith(b'+CGNSPWR: 1\r\n'):
                self.logger.info('GPS powered on')
            else:
                self.logger.error('Failed to power on GPS')
                raise Exception('Failed to power on GPS')
        except serial.SerialException as e:
            self.logger.error(f'Failed to power on GPS: {e}')

    def detach(self):
        try:
            self.serial.write(b'AT+CGNSPWR=0\r\n')
            time.sleep(1)
            response = self.serial.readline()
            if response.startswith(b'+CGNSPWR: 0\r\n'):
                self.logger.info('GPS powered off')
            else:
                self.logger.error('Failed to power off GPS')
                raise Exception('Failed to power off GPS')
        except serial.SerialException as e:
            self.logger.error(f'Failed to power off GPS: {e}')

    def get_data(self):
        try:
            response = self.serial.readline()
            if response.startswith(b'$GPRMC'):
                parts = response.decode('utf-8').split('\n')
                if len(parts) > 1 and parts[1].startswith('$GPRMC'):
                    status = parts[1].split(',')[2]
                    if status == 'A':
                        return parts[1].split(',')
                    else:
                        self.logger.error('Invalid or incomplete data')
                        return None
                else:
                    self.logger.error('No valid data available')
                    return None
            else:
                self.logger.error('No valid data available')
                return None
        except serial.SerialException as e:
            self.logger.error(f'Failed to read data: {e}')
            return None

def main():
    gps = Sim28GPS()
    try:
        with gps:
            gps.attach()
            while True:
                data = gps.get_data()
                if data is not None:
                    print(data)
                time.sleep(1)
    except KeyboardInterrupt:
        gps.detach()
    except Exception as e:
        gps.detach()
        raise e

if __name__ == '__main__':
    main()

