            self.serial = Serial(self.port, self.baudrate, timeout=self.config['TIMEOUT'])
            self.serial.timeout = self.config['TIMEOUT']
            self.serial.bytesize = serial.EIGHTBITS
            self.serial.parity = serial.PARITY_NONE
            self.serial.stopbits = serial.STOPBITS_ONE
            self.serial.close()
            self.serial = None
            return self
        except SerialException as e:
            raise e

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial:
            self.serial.close()

    def send(self, cmd):
        with self.lock:
            if not self.serial:
                raise SerialException('Serial port not open')
            cmd = cmd.encode()
            self.serial.write(cmd)
            self.serial.flush()
            if len(cmd) != self.serial.in_waiting:
                raise SerialException('Invalid byte count')

    def receive_line(self):
        with self.lock:
            if not self.serial:
                raise SerialException('Serial port not open')
            try:
                line = self.serial.readline()
                if not line:
