import serial
import time
import sys

def send_command(device, command):
    try:
        # Send the command to the device
        device.write(f'X{command}\n'.encode())
        # Wait for 0.1 seconds before sending the next command
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Serial connection error: {e}")

def main():
    # Open the serial connection to the Bluetooth device
    try:
        device = serial.Serial('/dev/rfcomm4', 38400, timeout=1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to open serial connection: {e}")

    try:
        while True:
            # Prompt the user for a command
            command = input("Enter a command (type 'exit' to quit): ")
            if command.lower() == 'exit':
                break

            # Send the command to the device
            send_command(device, command)
    except KeyboardInterrupt:
        # Handle KeyboardInterrupt to allow clean termination
        print("\nExiting...")
    finally:
        # Close the serial connection
        device.close()

if __name__ == "__main__":
    main()

